 {id:"t2-zah-team",tier:2,book:"ZAH",where:"Ch 13",title:"Find executive support (p. 257) · assess the organisation (p. 258) · review the current presence (p. 261) · build a team (p. 265)",pages:"pp. 256–268",why:"The people side: who does the work, and how to get leaders on board.",st:[2,6]},
 {id:"t2-zah-plan",tier:2,book:"ZAH",where:"Ch 14",title:"Social media marketing plan: audit (p. 273), listening and competitive analysis (p. 275), goals (p. 278), objectives (p. 279), strategies and target market (p. 280), tools (p. 281), platforms (p. 282), budgeting (p. 290), social ROI (p. 291)",pages:"pp. 270–292",why:"The whole plan, section by section. Use it as a checklist.",st:[2,3,4,6]},
 {id:"t2-zah-cafe",tier:2,book:"ZAH",where:"Appendix",title:"Caffé Daily social media marketing plan (worked example)",pages:"pp. 295–315",why:"A complete plan written out, for a café, like the example in your deck.",st:[6]},
 {id:"t2-kot-plan",tier:2,book:"KOT",where:"Ch 2",title:"The central role of strategic planning (p. 36) · corporate mission (p. 38) · business unit planning (p. 47) · SWOT (p. 48) · goal formulation (p. 50) · strategy formulation, Porter (pp. 50–53)",pages:"pp. 36–53",why:"The classic marketing-strategy base that social media strategy sits on.",st:[1,2,3]},
 {id:"t2-kot-mplan",tier:2,book:"KOT",where:"Ch 2",title:"The nature and contents of a marketing plan (pp. 54–55) · sample plan: Pegasus Sports International (pp. 60–64)",pages:"pp. 54–64",why:"What a full marketing plan looks like on paper.",st:[1,6]},
 {id:"t2-kot-seg",tier:2,book:"KOT",where:"Ch 8",title:"Bases for segmenting consumer markets (p. 214) · market targeting (p. 231)",pages:"pp. 214–235",why:"Standard segmentation and targeting, to back up the social audience profile.",st:[4]},
 {id:"t2-kot-pos",tier:2,book:"KOT",where:"Ch 10",title:"Developing and establishing a brand positioning · points of parity and difference (p. 280) · brand mantras (p. 284) · positioning bull's-eye (p. 287)",pages:"pp. 275–293",why:"Positioning is where the brand's social voice comes from.",st:[5]},
 {id:"t2-kot-imc",tier:2,book:"KOT",where:"Ch 17",title:"Developing effective communications: audience, objectives, design, channels (pp. 482–488) · budget (p. 488) · communications mix (p. 490) · measuring results and managing IMC (pp. 494–496)",pages:"pp. 482–496",why:"Social media as one part of integrated marketing communications.",st:[3,4,6]},
 {id:"t2-kot-wom",tier:2,book:"KOT",where:"Ch 19",title:"Interactive marketing (p. 540) · word of mouth and social media (p. 546) · buzz and viral marketing (p. 549) · opinion leaders (p. 551) · measuring word of mouth (p. 552)",pages:"pp. 540–552",why:"Background for advocacy, influence and calls to action.",st:[5]},
 {id:"t3-piskorski",tier:3,group:"Research and frameworks",title:"“Social Strategies That Work”",src:"Mikołaj Jan Piskorski · Harvard Business Review",date:"Nov 2011",url:"https://hbr.org/2011/11/social-strategies-that-work",why:"People want to connect with people, not with companies. A good social strategy helps people connect while doing useful work for the firm. May need an HBR login.",st:[1,5]},
 {id:"t3-ritson",tier:3,group:"Research and frameworks",title:"“Tactics without strategy is dumbing down our discipline”",src:"Mark Ritson · Marketing Week",date:"11 May 2016",url:"https://www.marketingweek.com/mark-ritson-beware-the-tactification-of-marketing/",why:"Research, segmentation, targeting and positioning come before tools and channels. A sharp opener for the strategy-vs-tactics point.",st:[1]},
 {id:"t3-felix",tier:3,group:"Research and frameworks",title:"“Elements of strategic social media marketing: A holistic framework”",src:"Felix, Rauschnabel & Hinsch · Journal of Business Research 70, 118–126",date:"2017",url:"https://doi.org/10.1016/j.jbusres.2016.05.001",why:"Four big choices: scope (defender to explorer), culture (conservative to modern), structure (hierarchy to network), governance (autocracy to anarchy).",st:[1,6]},
 {id:"t3-honeycomb",tier:3,group:"Research and frameworks",title:"“Social media? Get serious! Understanding the functional building blocks of social media”",src:"Kietzmann, Hermkens, McCarthy & Silvestre · Business Horizons 54(3), 241–251",date:"2011",url:"https://doi.org/10.1016/j.bushor.2011.01.005",why:"The “honeycomb”: seven building blocks (identity, conversations, sharing, presence, relationships, reputation, groups) for comparing what each platform is good at.",st:[4]},
 {id:"t3-post",tier:3,group:"Research and frameworks",title:"Groundswell, and its POST method",src:"Charlene Li & Josh Bernoff · Harvard Business Press (book)",date:"2008",why:"People, Objectives, Strategy, Technology: choose the platform last. Charlene Li is also quoted in Tuten & Solomon p. 42.",st:[3,4]},
 {id:"t3-amec",tier:3,group:"Research and frameworks",title:"AMEC Integrated Evaluation Framework",src:"AMEC (free to use)",date:"current",url:"https://amecorg.com/amecframework/",why:"A free planning-and-measurement tool: objectives, inputs, activities, outputs, out-takes, outcomes, impact. The Valid Metrics Framework in Zahay (p. 35) also came from AMEC.",st:[3,6]},
 {id:"t3-binet",tier:3,group:"Research and frameworks",title:"Les Binet & Peter Field: effectiveness research",src:"IPA · includes The Long and the Short of It (2013)",date:"archive",url:"https://ipa.co.uk/knowledge/effectiveness-research-analysis/les-binet-peter-field",why:"Evidence on balancing long-term brand building with short-term sales (the “60:40” guide). Mostly UK campaigns, so use it with care.",st:[3]},
 {id:"t3-datareportal",tier:3,group:"Data and industry guides",title:"Digital 2026: India",src:"DataReportal (Kepios)",date:"data to Oct 2025",url:"https://datareportal.com/reports/digital-2026-india",why:"500 million social media user identities in India (34.1% of people). Ad reach: YouTube 500M, Instagram 481M, Facebook 403M, Snapchat 213M, LinkedIn 170M members, X 22.2M.",st:[4]},
 {id:"t3-sprout",tier:3,group:"Data and industry guides",title:"Sprout Social Index 2025",src:"Sprout Social · press release",date:"7 Jan 2025",url:"https://sproutsocial.com/insights/press/the-days-of-trend-chasing-are-over-new-research-from-sprout-social-reveals-a-third-of-consumers-think-jumping-on-viral-trends-is-embarrassing-for-brands/",why:"A third of consumers find it embarrassing when brands jump on viral trends. 73% say they will buy from a rival if a brand does not respond on social.",st:[2,5]},
 {id:"t3-hootsuite",tier:3,group:"Data and industry guides",title:"“Master your 2026 social media strategy” (with free template)",src:"Hootsuite blog",date:"updated 2 Oct 2026",url:"https://blog.hootsuite.com/social-media-marketing-strategy/",why:"An industry seven-step version of the plan: goals, audience, competitors, audit, inspiration, content, measure. The article and template are free; the Hootsuite tool has no free plan.",st:[2,3,6]},
 {id:"t3-hubspot",tier:3,group:"Data and industry guides",title:"Social Media course",src:"HubSpot Academy · free online course",date:"current",url:"https://academy.hubspot.com/courses/social-media",why:"Video lessons on SMART goals, personas and social listening. Good for self-study, or as optional work for students.",st:[1,3,4]},
 {id:"t3-meta",tier:3,group:"News, 2025–2026",title:"“Meta aims to fully automate advertising with AI by 2026”",src:"exchange4media (citing the Wall Street Journal)",date:"3 Jun 2025",url:"https://www.exchange4media.com/digital-news/meta-aims-to-fully-automate-advertising-with-ai-by-2026-144037.html",why:"If AI makes the ads, picks the audience and splits the budget, the human job is the strategy: the objective and the audience.",st:[1]},
 {id:"t3-hashtags",tier:3,group:"News, 2025–2026",title:"Instagram caps hashtags at five per post (since Dec 2025)",src:"Later blog",date:"21 Apr 2026",url:"https://later.com/blog/instagram-hashtags/",why:"Platform rules change under your plan. This is why Zahay says “be flexible” (p. 38).",st:[4,6]},
 {id:"t3-itrules",tier:3,group:"News, 2025–2026",title:"“Govt tightens rules on AI-generated content, mandates labels and faster takedowns”",src:"Business Today",date:"10 Feb 2026",url:"https://www.businesstoday.in/amp/technology/story/govt-tightens-rules-on-ai-generated-content-mandates-labels-and-faster-takedowns-515505-2026-02-10",why:"India's amended IT Rules came into force on 20 Feb 2026. AI-made content must be clearly labelled, and platforms must act on some orders within three hours. A brand's social media policy should plan for both.",st:[6]},
 {id:"t3-amul",tier:3,group:"News, 2025–2026",title:"“How topical humour became Amul's strongest brand asset”",src:"exchange4media",date:"13 Jun 2026",url:"https://www.exchange4media.com/marketing-news/how-topical-humour-became-amuls-strongest-brand-asset-155425.html",why:"An Indian brand that kept one voice for decades and moved it from hoardings to Instagram and X. A clear example of a social persona and always-on content.",st:[5]}
